// __KV_V352: when nodes at the same head carry different histories, the
// majority chain wins (ties: lowest hash) — the same deterministic rule on
// every board, so every board adopts the SAME history. Never a sticky orderer.
async function ordLogAll(after){
  var L = await ordListF();
  var path = "/api/game/room/"+M.room+"/log?after="+(after||0);
  var rs = await Promise.allSettled(L.map(function(u){ return one(u, path); }));
  var got=[];
  for(var k=0;k<L.length;k++){
    var r=rs[k]; if(r.status!=="fulfilled" || !r.value) continue;
    var v=r.value;
    var h=(v.head!=null)?+v.head:(((v.entries||[]).length)+(after||0));
    got.push({u:L[k], v:v, h:h, c:String(v.chain||"")});
  }
  if(!got.length) return ord(path);   // every candidate failed the parallel read — old path decides
  var bestH=-1; for(var g=0;g<got.length;g++) if(got[g].h>bestH) bestH=got[g].h;
  var tops=got.filter(function(g){ return g.h===bestH; });
  var byChain={};                                                  // __KV_V352
  for(var t=0;t<tops.length;t++){ (byChain[tops[t].c]=byChain[tops[t].c]||[]).push(tops[t]); }
  var chains=Object.keys(byChain);
  chains.sort(function(a,b){ var d=byChain[b].length-byChain[a].length; return d!==0?d:(a<b?-1:1); });
  var winner=byChain[chains[0]][0];
  if(chains.length>1 && (!M.__splitLog || Date.now()-M.__splitLog>15000)){
    M.__splitLog=Date.now();
    log("relay content split at head "+bestH+": "+chains.length+" histories — adopting "+winner.u,"#e05050");
  }
  var bi=L.indexOf(winner.u);
  if(bi>=0 && M.ordIdx!==bi){ M.ordIdx=bi; log("reads pinned to the longest chain: "+winner.u+" (head "+bestH+")","#caa64c"); }
  for(var q=0;q<got.length;q++){ if(got[q].h<bestH && (!M.__lagLog || Date.now()-M.__lagLog>15000)){
    M.__lagLog=Date.now();
    log("relay divergence: "+got[q].u+" head "+got[q].h+" < "+bestH,"#e0a040");
  } }
  if(M.__pinChain && winner.c && winner.c!==M.__pinChain && bestH<=(M.__pinHead||0)){   // __KV_V352: history changed identity without growing
    M.__pinChain=winner.c; M.__pinHead=bestH;
    if(M.resync && (!M.__splitRs || Date.now()-M.__splitRs>20000)){
      M.__splitRs=Date.now();
      setTimeout(function(){ try{ M.resync("relay content split"); }catch(e){} },0);
    }
  } else { M.__pinChain=winner.c; M.__pinHead=bestH; }
  return winner.v;
}
M.ordLogAll = ordLogAll;
// __KV_V340: appends fan out to every node; the elected primary is authoritative
async function fanAppend(path, body){
  var L = await ordListF();
  var prim = L[(M.ordIdx||0) % L.length];
  var rs = await Promise.allSettled(L.map(function(u){ return one(u, path, body); }));
  var byU = {}, stored = 0;
  for(var k=0;k<L.length;k++){
    var r = rs[k];
    byU[L[k]] = (r.status==="fulfilled") ? r.value : null;
    var __fo=byU[L[k]];   // __KV_V361: the relay's dedup IS storage
    if(__fo && (__fo.stored===true || String(__fo.reason||"")==="duplicate" || String((__fo.result||{}).reason||"")==="duplicate")) stored++;
    else if(__fo){   // __KV_V362: a fulfilled non-store is a refusal — name it
      if(!M.__fanRef || Date.now()-M.__fanRef>10000){ M.__fanRef=Date.now();
        var __why=String(__fo.reason||(__fo.result||{}).reason||__fo.error||JSON.stringify(__fo).slice(0,60)||"unspecified");
        log("fan-out refused by "+L[k]+" — "+__why.slice(0,70), "#e0a040");
      }
    }
    else if(r.status==="rejected" && (!M.__fanErr || Date.now()-M.__fanErr>15000)){
      M.__fanErr=Date.now();
      log("fan-out miss: "+L[k]+" — "+String((r.reason&&r.reason.message)||r.reason||"no response").slice(0,80), "#e0a040");
    }
  }
  var po = byU[prim];
  if(po && (po.stored===true || po.stored===false)) {
    if(stored<L.length && (!M.__fanLog || Date.now()-M.__fanLog>10000)){
      M.__fanLog=Date.now();
      log("fan-out: stored on "+stored+"/"+L.length+" node(s)", stored>1?"#9cd87c":"#e0a040");
    }
    return po;
  }
  for(var q=0;q<L.length;q++){
    var alt = byU[L[q]];
    if(alt && alt.stored===true){
      M.ordIdx = q; M.ordList = L;
      log("fan-out failover: primary silent \u2014 adopted "+L[q], "#e0a040");
      return alt;
    }
  }
  for(var w=0;w<L.length;w++){ if(byU[L[w]]) return byU[L[w]]; }
  throw new Error("no node accepted "+path);
}
M.fanAppend = fanAppend;

window.KV_HOST2 = async function(){
  await discover();
  var a=new Uint8Array(4); crypto.getRandomValues(a);
  var room="kc"+Array.from(a).map(function(x){return x.toString(16).padStart(2,"0");}).join("");
  await fan("/api/game/room/create", { room:room, wallet:wallet(), seed_commit:"seed-"+room, game:"kascity" });
  localStorage.setItem("kv_mp2", JSON.stringify({ room:room, role:"host" }));
  log("ROOM "+room+" — share this code. Reloading into multiplayer...", "#9cd87c");
  setTimeout(function(){ location.reload(); }, 900);
  return room;
};
window.KV_JOIN2 = async function(code){
  code=String(code||"").trim();
  if(!code) { log("KV.join('<code>')","#ff6a4a"); return; }
  await discover();
  M.room=code;
  await fan("/api/game/room/"+code+"/join", { wallet:wallet() }, true);
  localStorage.setItem("kv_mp2", JSON.stringify({ room:code, role:"guest" }));
  log("joined "+code+" — reloading into multiplayer...", "#9cd87c");
  setTimeout(function(){ location.reload(); }, 900);
};
// __KV_V183: DAA helpers — the shared clock nobody owns
M.DAA_API = "https://api-tn10.kaspa.org/info/virtual-chain-blue-score";
async function daaNow(){
  var c=new AbortController(); var t=setTimeout(function(){c.abort();},5000);
  try{
    var r=await KV_WNET.req(M.DAA_API,{signal:c.signal});
    clearTimeout(t);
    var j=await r.json();
    var v = j.blueScore!=null ? j.blueScore : (j.virtualDaaScore!=null ? j.virtualDaaScore : null);
    return v==null ? null : Number(v);
  }catch(e){ clearTimeout(t); return null; }
}
async function sha256hex(str){
  var b=new TextEncoder().encode(str);
  var d=await crypto.subtle.digest("SHA-256", b);
  return Array.from(new Uint8Array(d)).map(function(x){return x.toString(16).padStart(2,"0");}).join("");
}
M.daaNow = daaNow;

// hold the lobby until the gun, then start both boards on the same DAA score
// __KV_V282: DAA-derived shared clock
M.__clk = { gun:null, gunAt:0, score:null, scoreAt:0, rate:null };
(function(){
  setInterval(async function(){
    try{
      if(!M.__clk.gun) return;
      var d=await M.daaNow();
      if(d==null) return;
      var now=Date.now();
      if(M.__clk.score!=null && now>M.__clk.scoreAt){
        var r=(d-M.__clk.score)/((now-M.__clk.scoreAt)/1000);
        if(r>0.2 && r<200) M.__clk.rate = (M.__clk.rate==null) ? r : (M.__clk.rate*0.7 + r*0.3);
      }
      M.__clk.score=d; M.__clk.scoreAt=now;
    }catch(e){}
  }, 5000);
})();
// seconds elapsed since the gun, from the chain score (null when unavailable)
window.KV_CLOCK_LEFT = function(total){
  try{
    var c=M.__clk;
    if(!M.room || !M.started || !c || !c.gun || c.score==null) return null;
    var rate = c.rate || 10;   // tn10 blue score advances ~10/s; measured above
    var scoreNow = c.score + rate*((Date.now()-c.scoreAt)/1000);   // smooth between samples
    var elapsed = (scoreNow - c.gun) / rate;
    if(!isFinite(elapsed) || elapsed<0) return null;
    return Math.max(0, Math.round((total||420) - elapsed));
  }catch(e){ return null; }
};
M.armGun = function(startDaa, seed, players){
  try{ M.__clk.gun = Number(startDaa); M.__clk.gunAt = Date.now(); }catch(eG){}   // __KV_V282
  if(M.gunArmed) return; M.gunArmed = true;
  M.startDaa = startDaa; M.seed = seed;
  if(seed){
    try{ if(window.KV_WORLD && window.KV_WORLD.meta) window.KV_WORLD.meta.seed = seed; }catch(e){}
    window.KV_SEED = seed;
  }
  log("start gun set for DAA "+startDaa+" — holding...", "#caa64c");
  var iv=setInterval(async function(){
    var now = await daaNow();
    if(now==null) return;
    var left = startDaa - now;
    if(left > 0){ log("starting in ~"+Math.ceil(left/10)+"s (DAA "+now+"/"+startDaa+")"); return; }
    clearInterval(iv);
    var n = (players||M.roster.length||2);
    // __KV_V185: this device controls ONE seat; the others are peers (relayed) or bots
    window.KV_HUMANS=[ M.seat||1 ];
    window.KV_SEATS_TOTAL = n;
    window.KV_MODE="p2p"; window.KV_XP_MULT=1.0;
    if(window.KV_SETSTATE && M.seat) window.KV_SETSTATE("hud_seat", M.seat);   // __KV_V236
    // __KV_V189: host's engine plays the bots (seats > roster); guest's engine waits for every other seat
    // __KV_V192: hud_seat is the engine's "this device controls seat X"; without it the engine never asks for input
    if(window.KV_SETSTATE){ window.KV_SETSTATE("humans", (M.role==="host" ? n : 4)); }   // __KV_V203: guest waits on every seat
    try{ if(window.__KV_LOBBY_OV) window.__KV_LOBBY_OV.remove(); }catch(e){}
    log("GO — "+n+" players, seat P"+(M.seat||1)+", DAA "+startDaa, "#9cd87c");
    // __KV_V197: every board's 7:00 starts here, at the gun — not at whoever tapped the lobby first
    try{
      var __w = window.KV_WORLD;
      if(window.KV_SETSTATE){
        window.KV_SETSTATE("over", 0);
        window.KV_SETSTATE("t0", (__w && __w.time) ? __w.time : 0.01);
        window.KV_SETSTATE("left", 420);
        window.KV_SETSTATE("mark", 420);
        M.__goAt = Date.now();   // __KV_V362: the gun is the one clock origin
      }
      window.KV_SEALED = false;
      log("clock reset to 7:00 at DAA "+startDaa, "#caa64c");
    }catch(e){}
    // __KV_V190: start the engine here, on the shared gun, not on a human tap
    (function kick(tries){
      var f=(window.KV_FLAGS&&window.KV_FLAGS())||{};
      if(f.t0>0){
        log("engine running", "#9cd87c");
        // __KV_V191: the host opens a bot's first turn; humans open their own by tapping Roll
        if(M.role==="host"){
          (function openBot(t2){
            var g=(window.KV_FLAGS&&window.KV_FLAGS())||{};
            var rolled=(window.KV_MOVES||[]).some(function(m){ return m.a==="roll"; });
            if(rolled) return;
            var firstDone=(window.KV_MOVES||[]).filter(function(m){ return m.a==="first"; }).length>=4
                          && !document.querySelector("[data-kvmodal]");
            if(!firstDone){ if(t2<80) setTimeout(function(){ openBot(t2+1); }, 300); return; }
            var seat=g.seat||(((g.turn||0)%4)+1);
            try{ var __fw={}, __fn=0, __mvO=window.KV_MOVES||[];   // __KV_V356+V358: ACKED firsts only
              for(var __oi2=0;__oi2<__mvO.length;__oi2++){ var __orX=__mvO[__oi2];
                if(__orX&&__orX.__acked&&String(__orX.a)==="first"&&__fw[__orX.s]==null){ __fw[__orX.s]=+__orX.v; __fn++; } }
              if(__fn<4){                                       // __KV_V358: the contest is not on-chain yet
                if(t2<80) setTimeout(function(){ openBot(t2+1); }, 300);
                return;
              }
              var __bw=null;
              for(var __s2=1;__s2<=4;__s2++){ if(__fw[__s2]!=null&&(__bw==null||__fw[__s2]>__fw[__bw])) __bw=__s2; }
              if(__bw) seat=__bw;
            }catch(__eW){}
            // __KV_V243: publish the opener so the relay gate knows who rolls first
            if(!M.__openerSent){ M.__openerSent=1;
              try{ fanAppend("/api/game/room/"+M.room+"/append", { wallet:wallet(), kind:"move",
                body:{ s:seat, a:"opener", v:0, t:0 } }).catch(function(){}); }catch(eO){}
              log("opener published: P"+seat+" rolls first", "#caa64c");
            }
            var isBot = M.roster.length && seat>M.roster.length;
            if(isBot){ log("opening bot P"+seat+"'s turn", "#caa64c"); if(window.KV_SETSTATE) window.KV_SETSTATE("go",0); }
            else log("P"+seat+" opens — that player taps Roll", "#caa64c");
          })(0);
        }
        return;
      }
      if(tries>40){ log("engine did not start — tap the board", "#ff6a4a"); return; }
      try{
        var c=document.querySelector("canvas");
        if(c){ var r=c.getBoundingClientRect();
          var o={bubbles:true,cancelable:true,clientX:r.left+3,clientY:r.top+3,pointerId:1,pointerType:"mouse",isPrimary:true,button:0};
          c.dispatchEvent(new PointerEvent("pointerdown",o));
          c.dispatchEvent(new PointerEvent("pointerup",o)); }
        document.dispatchEvent(new Event("pointerdown"));
      }catch(e){}
      setTimeout(function(){ kick(tries+1); }, 250);
    })(0);
    if(window.KV_SHOUT) window.KV_SHOUT("GO", "all boards start together", "#9cd87c", true);
  }, 1000);
};

window.KV_START2 = async function(){
  if(!M.room){ log("host first: KV.host()","#ff6a4a"); return; }
  // merged view of who joined across all nodes, ordered by join time, host first
  var infos = await fan("/api/game/room/"+M.room, undefined, true);
  var by={};
  infos.forEach(function(r){ (r.players||[]).forEach(function(p){
    if(by[p.wallet]==null || p.joined_at<by[p.wallet]) by[p.wallet]=p.joined_at; }); });
  var roster=Object.keys(by).sort(function(a,b){
    if(a===wallet()) return -1; if(b===wallet()) return 1;
    return by[a]-by[b] || (a<b?-1:1); });
  await fan("/api/game/room/"+M.room+"/start", { roster:roster, turn_order:{ seats:4, round_robin:["roll"], follow:["buy","pass","end","court"], dice:["roll"], exempt:["first"], seed:["opener"], derive_opener_from:"first" } });
  M.roster=roster; applyRoster(roster);
  // __KV_V183: reveal the seed and set the DAA gun ~8s out, published as move index -1
  var seed = "kc"+M.room+"-"+Date.now().toString(36);
  var now = await daaNow();
  if(now==null){ log("DAA unavailable — cannot set a fair start gun","#ff6a4a"); return; }
  var startDaa = Math.round(now) + 80;   // ~8s at ~10 blocks/sec (rate measured live for the clock)
  await fanAppend("/api/game/room/"+M.room+"/append", { wallet:wallet(), kind:"gun",
    body:{ startDaa:startDaa, seed:seed, seedHash: await sha256hex(seed), players:roster.length } });
  M.armGun(startDaa, seed, roster.length);
  log("game started — "+roster.length+" player(s), gun at DAA "+startDaa);
};

function applyRoster(roster){
  // __KV_V305: the legacy path runs the game again; KV_RELAY2 observes only
  M.roster=roster; M.started=true;
  M.seat=roster.indexOf(wallet())+1;
  if(M.seat<1) M.seat=1;
  if(window.KV_NET) window.KV_NET.seat=M.seat;   // the commit checker reads this
  if(window.KV_SETSTATE) window.KV_SETSTATE("hud_seat", M.seat);   // __KV_V236: this device controls seat X
  window.KV_HUMANS=[ M.seat||1 ];              // __KV_V185: own seat only
  window.KV_SEATS_TOTAL = roster.length;
  if(window.KV_SETSTATE){ window.KV_SETSTATE("humans", roster.length); }   // __KV_V285: both boards agree
  log("you are P"+M.seat+" of "+roster.length, COL[M.seat]||"#caa64c");
  strip();
}

// ---- outbound (__KV_V189): tail the record itself, so watcher-recorded moves relay too ----
// host sends its own seat AND every bot seat (seat > roster length); guest sends its own seat only
(function(){
  var sent={};
  function mine(seat){
    if(seat===M.seat) return true;
    if(M.role==="host" && M.roster.length && seat>M.roster.length) return true;   // host still publishes bot moves so the guest can verify
    return false;
  }
  setInterval(function(){
    if(!M.started || !M.room || M.halted) return;
    var list=window.KV_MOVES||[];
    for(var i=0;i<list.length;i++){
      var rec=list[i];
      if(!rec || rec.__sent) continue;
      if(!mine(rec.s)) continue;   // __KV_V202: publish only the seats this client owns
      // __KV_V241: hold turn-bound records until the chain says this seat is eligible
      var __a=String(rec.a);
      if(__a==="roll" || __a==="buy" || __a==="pass"){
        var __mvG=(window.KV_MOVES||[]), __lr=null, __gi=-1;
        for(var __g=__mvG.length-1;__g>=0;__g--){ var __r=__mvG[__g];
          if(__r && __r!==rec && String(__r.a)==="roll"){ __lr=__r; __gi=__g; break; } }
        if(__a==="roll"){
          if(__lr){
            if(rec.s!==((__lr.s%4)+1)) continue;
            // __KV_V247: previous roller must progress first (bot 3.5s / human 20s grace)
            var __dn2=false;
            for(var __u2=__gi+1;__u2<__mvG.length;__u2++){ var __q2=__mvG[__u2]; if(__q2 && __q2!==rec && __q2.__acked && __q2.s===__lr.s){ __dn2=true; break; } }
            if(!__dn2){
              var __bot2=(M.roster && M.roster.length && __lr.s>M.roster.length);
              if(Date.now()-(M.__lastLogAt||0) < (__bot2?3500:6000)) continue;   // __KV_V249
            }
          }
          else { var __op=M.opener; if(__op!=null && rec.s!==__op) continue; }   // __KV_V243
        }
        else { if(!__lr || __lr.s!==rec.s) continue; }
      }
      if(rec.hash==null) continue;              // wait for the choke-point commit
      if(M.__posting) break;   // __KV_V255: serialize -- arrival order must match record order
      M.__posting = 1;
      rec.__sent=1;
      (function(r){
        try{ if(window.KV_SNAPSHOT) r.snap = window.KV_SNAPSHOT(); }catch(eS){}   // __KV_V256: post-effect state
        fanAppend("/api/game/room/"+M.room+"/append", { wallet:wallet(), kind:"move",
          body:{ s:r.s, a:String(r.a), v:r.v, t:r.t, hash:r.hash, snap:r.snap||null, fx:r.fx||null } })
        .then(function(o){
          M.__posting = 0;
          if(o && o.stored===false && o.reason){
            // __KV_V263: advisory moves (end/court) are best-effort — drop, no retry, no resync
            var __adv=(String(r.a)==="end"||String(r.a)==="court");
            if(__adv){
              var mvA=(window.KV_MOVES||[]);
              if(mvA[r.i]===r) delete mvA[r.i];
              r.__sent=1; r.__acked=1; r.__dropped=1;
              return;
            }
            log("relay refused "+r.a+" P"+r.s+": "+o.reason+(o.detail?(" ["+o.detail+"]"):"")+(o.expect!=null?(" (expects P"+o.expect+")"):""), "#e0a040");
            if(o.reason==="bad_transition"){
              try{
                var __prev=null, __mvD=(window.KV_MOVES||[]);
                for(var __d=__mvD.length-1;__d>=0;__d--){ var __q=__mvD[__d]; if(__q && __q!==r && __q.__acked && __q.snap){ __prev=__q; break; } }
                console.warn("[KV BAD_TRANSITION]", o.detail||"?", {
                  action:r.a, seat:r.s, v:r.v, d1:r.d1, d2:r.d2,
                  prevSnap:(__prev?__prev.snap:null), prevAt:(__prev?__prev.i:null), prevAction:(__prev?__prev.a:null),
                  nextSnap:r.snap
                });
                log("  detail: "+(o.detail||"?")+" \u00b7 prev@"+(__prev?__prev.i:"-")+" "+(__prev?__prev.snap:"-"), "#8a7a5a");
                log("  ours:   "+(r.snap||"-"), "#8a7a5a");
              }catch(eD){}
            }
            // __KV_V271: gate refusal = the move never happened; the relay's expect is authoritative
            var __gate=/not_your_turn|not_the_roller|opener_mismatch|not_the_opener/.test(String(o.reason||""));
            if(__gate){
              var mvG=(window.KV_MOVES||[]);
              if(mvG[r.i]===r) delete mvG[r.i];
              r.__sent=1; r.__acked=1; r.__dropped=1;
              var ex=+o.expect;
              if(ex>=1 && ex<=4 && window.KV_SETSTATE){
                if(window.KV_TURN_CTL){ M.requestStep(ex,"gate-refusal"); }   // __KV_V285
                else { window.KV_SETSTATE("turn", ex-1); window.KV_SETSTATE("seat", ex);
                window.KV_SETSTATE("phase",0); window.KV_SETSTATE("moved",0);
                var __goR=(ex===M.seat || (M.owns&&M.owns(ex))) ? -1 : 0;
                window.KV_SETSTATE("asked",0); window.KV_SETSTATE("go",__goR); }
                if(ex>=1 && ex<=4){ M.__relayTurn={ exp:ex, last:(M.__relayTurn?M.__relayTurn.last:null), at:Date.now() }; }   // __KV_V292
            log("relay expects P"+ex, "#caa64c");
              } else if(M.resync){ M.resync("relay refused "+r.a); }
              return;
            }
            r.__sent=0;
            if(M.resync) M.resync("relay refused "+r.a);
            return;
          }
          if(!o || o.stored!==true || o.i==null){ r.__sent=0; return; }
          M.seen[o.i]=1;                 // our own entry: the /log echo is not re-applied
          if(String(r.a)==="roll"){ M.__lastRollRx={ s:r.s, i:o.i, at:Date.now() }; }   // __KV_V275
          if(o.d1!=null && String(r.a)==="roll" && (+r.v)!==((+o.d1)+(+o.d2))){
            r.v=(+o.d1)+(+o.d2); r.d1=+o.d1; r.d2=+o.d2;
            log("relay corrected dice at i"+o.i+" \u2014 resyncing","#e0a040");
            if(M.resync){ M.__lastResync=0; M.resync("dice corrected"); }
          }
          r.__acked=1;                   // __KV_V256: chain-confirmed
          if(o.i !== r.i){
            var mv=(window.KV_MOVES||[]);
            if(mv[r.i]===r) delete mv[r.i];
            r.i = o.i; mv[o.i] = r;
            try{
              if(window.KV_COMMIT && window.KV_COMMIT.add){
                window.KV_COMMIT.add(r.i, r.s, r.a, r.v, r.snap).then(function(h2){ r.hash = h2; }).catch(function(){});
              }
            }catch(e){}
